def minPathSumWithWaivers(grid, k):
    INF = float("inf")
    n = len(grid[0])
    prev = None
    for r, row in enumerate(grid):
        cur = [[INF] * n for _ in range(k + 1)]
        for c in range(n):
            v = row[c]
            for j in range(k + 1):
                if r == 0 and c == 0:
                    if j == 0:
                        cur[0][0] = v
                    elif j == 1:
                        cur[1][0] = 0
                    continue
                pay = INF
                if r > 0:
                    pay = prev[j][c]
                if c > 0 and cur[j][c - 1] < pay:
                    pay = cur[j][c - 1]
                best = pay + v
                if j > 0:
                    free = INF
                    if r > 0:
                        free = prev[j - 1][c]
                    if c > 0 and cur[j - 1][c - 1] < free:
                        free = cur[j - 1][c - 1]
                    if free < best:
                        best = free
                cur[j][c] = best
        prev = cur
    return min(prev[j][n - 1] for j in range(k + 1))
